<?php
namespace Modules\Academy\Services;
use Core\database\DB;use Modules\System\Services\SiteAdminAccess;use RuntimeException;
class AcademySubscriptionService{
 public function index(int$a):array{$academies=$this->academies($a);foreach($academies as$academy)$this->sync((int)$academy['academy_id']);$ids=array_map(fn($x)=>(int)$x['academy_id'],$academies);$periods=$ids?DB::table('academy_subscription_periods')->whereIn('academy_id',$ids)->whereNull('deleted_at')->orderBy('period_start','DESC')->get():[];$translations=[];foreach($academies as$x)$translations[(int)$x['academy_id']]=$this->title((int)$x['academy_id']);return['monthlyPrice'=>$this->price(),'currency'=>$this->currency(),'periods'=>array_map(fn($p)=>['id'=>(int)$p['subscription_period_id'],'academyId'=>(int)$p['academy_id'],'academyName'=>$translations[(int)$p['academy_id']]??'آموزشگاه','start'=>$p['period_start'],'end'=>$p['period_end'],'dueDate'=>$p['due_date'],'amount'=>(int)$p['amount'],'statusCode'=>$p['status'],'status'=>match($p['status']){'free'=>'ماه اول رایگان','paid'=>'پرداخت‌شده','pending'=>'در انتظار پرداخت','expired'=>'منقضی‌شده',default=>'لغوشده'},'canPay'=>in_array($p['status'],['pending','expired'],true)&&(int)$p['amount']>0],$periods)];}
 public function sync(int$id):void{$academy=DB::table('academies')->where('academy_id',$id)->whereNull('deleted_at')->first();if(!$academy)return;$start=substr((string)($academy['created_at']?:date('Y-m-d')),0,10);$end=(new \DateTimeImmutable($start))->modify('+1 month')->format('Y-m-d');$now=date('Y-m-d H:i:s');$first=DB::table('academy_subscription_periods')->where('academy_id',$id)->where('period_start',$start)->first();if(!$first)DB::table('academy_subscription_periods')->insert(['academy_id'=>$id,'period_start'=>$start,'period_end'=>$end,'amount'=>0,'currency'=>$this->currency(),'status'=>'free','due_date'=>$start,'paid_at'=>$now,'created_at'=>$now,'created_by'=>(int)$academy['user_id'],'updated_at'=>$now,'updated_by'=>(int)$academy['user_id']]);$latest=DB::table('academy_subscription_periods')->where('academy_id',$id)->whereNull('deleted_at')->orderBy('period_end','DESC')->first();if(!$latest)return;$today=new \DateTimeImmutable('today');$latestEnd=new \DateTimeImmutable($latest['period_end']);if(in_array($latest['status'],['pending'],true)&&$latestEnd<$today)DB::table('academy_subscription_periods')->where('subscription_period_id',(int)$latest['subscription_period_id'])->update(['status'=>'expired','updated_at'=>$now]);if($today<$latestEnd->modify('-3 days'))return;$nextStart=$latest['period_end'];$nextEnd=(new \DateTimeImmutable($nextStart))->modify('+1 month')->format('Y-m-d');if(!DB::table('academy_subscription_periods')->where('academy_id',$id)->where('period_start',$nextStart)->first())DB::table('academy_subscription_periods')->insert(['academy_id'=>$id,'period_start'=>$nextStart,'period_end'=>$nextEnd,'amount'=>$this->price(),'currency'=>$this->currency(),'status'=>'pending','due_date'=>$nextStart,'created_at'=>$now,'created_by'=>(int)$academy['user_id'],'updated_at'=>$now,'updated_by'=>(int)$academy['user_id']]);}
 public function start(int$a,int$periodId):array{$merchant=trim((string)env('ZARINPAL_MERCHANT_ID',''));if($merchant==='')throw new RuntimeException('شناسه پذیرنده زرین‌پال تنظیم نشده است.');$period=$this->period($a,$periodId);if(!in_array($period['status'],['pending','expired'],true)||(int)$period['amount']<1)throw new RuntimeException('این دوره قابل پرداخت نیست.');$token=bin2hex(random_bytes(32));$now=date('Y-m-d H:i:s');$pid=(int)DB::table('academy_subscription_payments')->insertGetId(['subscription_period_id'=>$periodId,'academy_id'=>(int)$period['academy_id'],'user_id'=>$a,'amount'=>(int)$period['amount'],'currency'=>$period['currency'],'callback_token'=>$token,'status'=>'created','created_at'=>$now,'created_by'=>$a,'updated_at'=>$now,'updated_by'=>$a]);$callback=rtrim((string)env('APP_URL',$this->origin()),'/').'/academy/subscriptions/zarinpal/callback?token='.$token;try{$result=$this->request('/pg/v4/payment/request.json',['merchant_id'=>$merchant,'amount'=>(int)$period['amount'],'currency'=>$period['currency'],'callback_url'=>$callback,'description'=>'اشتراک ماهانه سامانه مدیریت آموزشگاه','metadata'=>[]]);$code=(int)($result['data']['code']??0);$authority=(string)($result['data']['authority']??'');if($code!==100||$authority==='')throw new RuntimeException((string)($result['errors']['message']??'ایجاد پرداخت اشتراک ناموفق بود.'));DB::table('academy_subscription_payments')->where('subscription_payment_id',$pid)->update(['authority'=>$authority,'status'=>'pending','gateway_code'=>$code,'requested_at'=>$now,'updated_at'=>$now]);$sandbox=filter_var(env('ZARINPAL_SANDBOX',false),FILTER_VALIDATE_BOOL);return['redirectUrl'=>($sandbox?'https://sandbox.zarinpal.com':'https://www.zarinpal.com').'/pg/StartPay/'.$authority];}catch(\Throwable$e){DB::table('academy_subscription_payments')->where('subscription_payment_id',$pid)->update(['status'=>'failed','gateway_message'=>mb_substr($e->getMessage(),0,500),'updated_at'=>$now]);throw$e;}}
 public function callback(string$token,string$authority,string$status):array{$payment=DB::table('academy_subscription_payments')->where('callback_token',$token)->whereNull('deleted_at')->first();if(!$payment||!hash_equals((string)($payment['authority']??''),$authority))throw new RuntimeException('شناسه پرداخت اشتراک معتبر نیست.');if($payment['status']==='paid')return['success'=>true,'referenceId'=>$payment['reference_id']];if(strtoupper($status)!=='OK'){DB::table('academy_subscription_payments')->where('subscription_payment_id',(int)$payment['subscription_payment_id'])->update(['status'=>'canceled','updated_at'=>date('Y-m-d H:i:s')]);return['success'=>false];}$result=$this->request('/pg/v4/payment/verify.json',['merchant_id'=>(string)env('ZARINPAL_MERCHANT_ID',''),'amount'=>(int)$payment['amount'],'authority'=>$authority]);$code=(int)($result['data']['code']??0);if(!in_array($code,[100,101],true))throw new RuntimeException((string)($result['errors']['message']??'تأیید پرداخت اشتراک ناموفق بود.'));$ref=(string)($result['data']['ref_id']??'');$now=date('Y-m-d H:i:s');transaction(function()use($payment,$code,$ref,$now){DB::table('academy_subscription_payments')->where('subscription_payment_id',(int)$payment['subscription_payment_id'])->update(['status'=>'paid','reference_id'=>$ref,'gateway_code'=>$code,'verified_at'=>$now,'updated_at'=>$now]);DB::table('academy_subscription_periods')->where('subscription_period_id',(int)$payment['subscription_period_id'])->update(['status'=>'paid','paid_at'=>$now,'updated_at'=>$now,'updated_by'=>(int)$payment['user_id']]);});return['success'=>true,'referenceId'=>$ref];}
 private function period(int$a,int$id):array{$allowed=array_column($this->academies($a),'academy_id');$p=DB::table('academy_subscription_periods')->where('subscription_period_id',$id)->whereNull('deleted_at')->first();if(!$p||!in_array((int)$p['academy_id'],array_map('intval',$allowed),true))throw new RuntimeException('دوره اشتراک در محدوده شما نیست.');return$p;}private function academies(int$a):array{$u=DB::table('users')->where('user_id',$a)->whereNull('deleted_at')->first();if(!$u)throw new RuntimeException('کاربر معتبر نیست.');if(SiteAdminAccess::allows($u))return DB::table('academies')->whereNull('deleted_at')->get();$rows=array_merge(DB::table('academies')->where('user_id',$a)->whereNull('deleted_at')->get(),DB::table('academies')->where('created_by',$a)->whereNull('deleted_at')->get());foreach(DB::table('academy_branch_members')->where('user_id',$a)->whereNull('deleted_at')->get()as$m){$role=DB::table('academy_branch_member_roles')->join('access_system_roles','access_system_roles.role_id','=','academy_branch_member_roles.role_id')->where('academy_branch_member_roles.member_id',(int)$m['member_id'])->whereRaw("LOWER(access_system_roles.name) LIKE '%manager%' OR LOWER(access_system_roles.name) LIKE '%owner%'")->whereNull('academy_branch_member_roles.deleted_at')->whereNull('access_system_roles.deleted_at')->first();if($role)$rows=array_merge($rows,DB::table('academies')->where('academy_id',(int)$m['academy_id'])->whereNull('deleted_at')->get());}$unique=[];foreach($rows as$r)$unique[(int)$r['academy_id']]=$r;if(!$unique)throw new RuntimeException('آموزشگاه مرتبط یافت نشد.');return array_values($unique);}private function price():int{return max(0,(int)env('ACADEMY_MONTHLY_SUBSCRIPTION_PRICE',0));}private function currency():string{return strtoupper((string)env('ZARINPAL_CURRENCY','IRT'))==='IRR'?'IRR':'IRT';}private function title(int$id):string{$t=DB::table('translations')->where('table_name','academies')->where('table_id',$id)->whereIn('field',['title','name'])->where('locale','fa')->whereNull('deleted_at')->first();return(string)($t['value']??'آموزشگاه '.$id);}private function request(string$path,array$data):array{$host=filter_var(env('ZARINPAL_SANDBOX',false),FILTER_VALIDATE_BOOL)?'https://sandbox.zarinpal.com':'https://api.zarinpal.com';$ch=curl_init($host.$path);curl_setopt_array($ch,[CURLOPT_POST=>true,CURLOPT_POSTFIELDS=>json_encode($data,JSON_UNESCAPED_UNICODE),CURLOPT_RETURNTRANSFER=>true,CURLOPT_TIMEOUT=>30,CURLOPT_HTTPHEADER=>['Content-Type: application/json','Accept: application/json']]);$raw=curl_exec($ch);$error=curl_error($ch);curl_close($ch);if($raw===false||$error)throw new RuntimeException('ارتباط با زرین‌پال برقرار نشد: '.$error);$r=json_decode($raw,true);if(!is_array($r))throw new RuntimeException('پاسخ زرین‌پال معتبر نیست.');return$r;}private function origin():string{return((!empty($_SERVER['HTTPS'])&&$_SERVER['HTTPS']!=='off')?'https':'http').'://'.($_SERVER['HTTP_HOST']??'localhost');}
}
